using StardewModdingAPI;\nusing StardewValley;\nusing System;\n\nnamespace EnhancedSchoolsMod\n{\n    public class TermHandler\n    {\n        private readonly ModConfig Config;\n        private readonly IMonitor Monitor;\n\n        public TermHandler(ModConfig config, IMonitor monitor) { Config = config; Monitor = monitor; }\n\n        public int GetCurrentSeasonNumber() => Game1.currentSeason switch { \"spring\" => 0, \"summer\" => 1, \"fall\" => 2, \"winter\" => 3, _ => 0 };\n\n        public bool IsCurrentlyOnHoliday()\n        {\n            string currentSeason = Game1.currentSeason;\n            int currentDay = Game1.dayOfMonth;\n            foreach (var holiday in Config.HolidaySchedule.Values)\n            {\n                if (holiday.Season.ToLower() == currentSeason && currentDay >= holiday.StartDay && currentDay <= holiday.EndDay)\n                    return true;\n            }\n            return false;\n        }\n\n        public string GetCurrentHolidayName()\n        {\n            string currentSeason = Game1.currentSeason;\n            int currentDay = Game1.dayOfMonth;\n            foreach (var holiday in Config.HolidaySchedule.Values)\n            {\n                if (holiday.Season.ToLower() == currentSeason && currentDay >= holiday.StartDay && currentDay <= holiday.EndDay)\n                    return holiday.Name;\n            }\n            return \"\";\n        }\n\n        public int GetDayInTerm() => Math.Min(Game1.dayOfMonth, Config.TermLengthDays);\n        public int GetDaysRemainingInTerm() => Math.Max(0, Config.TermLengthDays - GetDayInTerm());\n\n        public SchoolTerm GetCurrentTermInfo()\n        {\n            var term = new SchoolTerm { Season = Game1.currentSeason, StartDay = 1, EndDay = Config.TermLengthDays };\n            foreach (var holiday in Config.HolidaySchedule.Values)\n            {\n                if (holiday.Season.ToLower() == Game1.currentSeason)\n                {\n                    term.HolidayName = holiday.Name;\n                    term.HolidayStartDay = holiday.StartDay;\n                    term.HolidayEndDay = holiday.EndDay;\n                    break;\n                }\n            }\n            return term;\n        }\n    }\n}